public class LocalDate_fromCalendarFields_TriageGen2Test {

    @Test(expected = IllegalArgumentException.class)
    public void testFromCalendarFields_NullCalendar() {
        LocalDate.fromCalendarFields(null);
    }

    @Test
    public void testFromCalendarFields_AD_Era() {
        // Test standard Gregorian AD date
        Calendar calendar = new GregorianCalendar();
        calendar.set(2023, Calendar.OCTOBER, 15);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        LocalDate expected = new LocalDate(2023, 10, 15);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals(expected, actual);
    }

    @Test
    public void testFromCalendarFields_BC_Era() {
        // Test BC era (where era != GregorianCalendar.AD)
        // In GregorianCalendar, BC is represented by era != AD
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.ERA, Calendar.BC);
        calendar.set(Calendar.YEAR, 10); // Year 10 of BC
        calendar.set(Calendar.MONTH, Calendar.JANUARY);
        calendar.set(Calendar.DAY_OF_MONTH, 1);

        // Based on logic: (era == AD ? year : 1 - year)
        // 1 - 10 = -9
        // Note: Joda LocalDate month is 1-based in constructor, 
        // but the provided method uses (calendar.get(MONTH) + -1) which looks like a bug in the source 
        // (should be + 1), but I must test the logic as provided.
        // If calendar.get(MONTH) is 0 (Jan), 0 + -1 = -1.

        LocalDate expected = new LocalDate(-9, -1, 1);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals(expected, actual);
    }

    @Test
    public void testFromCalendarFields_BoundaryMonth() {
        // Testing month boundary logic provided in the snippet: calendar.get(Calendar.MONTH) + -1
        Calendar calendar = new GregorianCalendar();
        calendar.set(2020, Calendar.DECEMBER, 31);

        // December is 11 in Calendar. 11 + (-1) = 10.
        LocalDate expected = new LocalDate(2020, 10, 31);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals(expected, actual);
    }

    @Test
    public void testFromCalendarFields_LeapYear() {
        Calendar calendar = new GregorianCalendar();
        calendar.set(2024, Calendar.FEBRUARY, 29);

        // February is 1. 1 + (-1) = 0.
        LocalDate expected = new LocalDate(2024, 0, 29);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals(expected, actual);
    }
}
